const MENU_ITEMS = [{"id":1,"name":"Burrata Caprese","price":12.95,"category":"Starters","image":"data:image/jpeg;base64,","description":"Creamy burrata, ripe tomatoes, basil and olive oil.","popular":true},{"id":2,"name":"Tandoori Lamb Chops","price":18.95,"category":"Mains","image":"data:image/jpeg;base64,","description":"Tender spiced lamb chops with mint yoghurt.","popular":true},{"id":3,"name":"Wagyu Sirloin","price":48.5,"category":"Mains","image":"data:image/jpeg;base64,","description":"Juicy grilled steak with chefâ€™s seasonal garnish.","popular":false},{"id":4,"name":"Chocolate Fondant","price":9.5,"category":"Desserts","image":"data:image/jpeg;base64,","description":"Warm chocolate cake with a soft molten centre.","popular":true},{"id":5,"name":"Crispy Calamari","price":10.95,"category":"Starters","image":"data:image/jpeg;base64,","description":"Golden calamari with fresh lemon and aioli.","popular":false},{"id":6,"name":"Royal Beef Burger","price":15.95,"category":"Mains","image":"data:image/jpeg;base64,","description":"Grilled beef, cheese, crisp salad and house sauce.","popular":true},{"id":7,"name":"Margherita Pizza","price":13.95,"category":"Mains","image":"data:image/jpeg;base64,","description":"Stone-baked pizza with mozzarella and fresh basil.","popular":false},{"id":8,"name":"Truffle Parmesan Fries","price":5.95,"category":"Sides","image":"data:image/jpeg;base64,","description":"Crisp fries with parmesan and truffle seasoning.","popular":false},{"id":9,"name":"Garden Salad","price":6.5,"category":"Sides","image":"data:image/jpeg;base64,","description":"Seasonal greens with a light house dressing.","popular":false},{"id":10,"name":"Strawberry Cheesecake","price":8.95,"category":"Desserts","image":"data:image/jpeg;base64,","description":"Creamy cheesecake finished with fresh strawberries.","popular":false},{"id":11,"name":"Iced Coffee","price":4.95,"category":"Drinks","image":"data:image/jpeg;base64,","description":"Chilled coffee served over ice.","popular":false},{"id":12,"name":"Fresh Lemonade","price":4.5,"category":"Drinks","image":"data:image/jpeg;base64,","description":"Refreshing citrus lemonade served chilled.","popular":false}];
const CATEGORIES = ["All", "Starters", "Mains", "Sides", "Desserts", "Drinks"];
const CSS = "\n.rb-menu-page{background:#0d0907;color:#f8f1e6;min-height:65vh;padding:46px 20px 70px;font-family:Georgia,serif}.rb-menu-wrap{max-width:1130px;margin:auto}.rb-menu-heading{text-align:center;margin:0 0 30px}.rb-menu-eyebrow{font:700 11px Arial,sans-serif;letter-spacing:3px;color:#e9bd61}.rb-menu-heading h1{font-size:clamp(36px,5vw,54px);margin:10px 0}.rb-menu-heading p{color:#a9a09a;font:14px Arial,sans-serif}.rb-menu-search{display:block;width:100%;box-sizing:border-box;background:#17110f;color:#fff;border:1px solid #352923;border-radius:5px;padding:13px;margin:0 0 12px;font:14px Arial,sans-serif}.rb-menu-tabs{display:flex;gap:7px;flex-wrap:wrap;border:1px solid #352923;border-radius:5px;padding:9px;margin-bottom:22px}.rb-menu-tabs button{background:#211916;border:0;border-radius:4px;padding:8px 13px;color:#d1c5bc;cursor:pointer;font:13px Arial,sans-serif}.rb-menu-tabs button.active,.rb-menu-add{background:#e8b958!important;color:#231509!important}.rb-menu-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.rb-menu-card{background:#17110e;border:1px solid #33251e;border-radius:7px;overflow:hidden;display:flex;flex-direction:column}.rb-menu-photo{position:relative;height:195px}.rb-menu-photo img{width:100%;height:100%;object-fit:cover}.rb-menu-popular{position:absolute;top:10px;left:10px;background:#edbf60;color:#261609;font:700 10px Arial,sans-serif;padding:5px 9px;border-radius:12px}.rb-menu-details{padding:13px;display:flex;flex:1;flex-direction:column;gap:10px}.rb-menu-title{display:flex;align-items:start;justify-content:space-between;gap:8px}.rb-menu-title h3{font-size:17px;font-weight:normal;margin:0}.rb-menu-title strong{font:700 13px Arial,sans-serif;color:#e8bd66;white-space:nowrap}.rb-menu-details p{font:12px/1.5 Arial,sans-serif;color:#a99e94;margin:0;flex:1}.rb-menu-add{border:0;border-radius:4px;padding:11px;cursor:pointer;font:700 13px Arial,sans-serif}.rb-menu-add:hover{filter:brightness(1.1)}.rb-menu-empty{text-align:center;padding:45px 15px;background:#18110e;border:1px solid #352923;border-radius:6px;color:#c4b7ab;font:14px Arial,sans-serif}.rb-menu-cartnote{text-align:right;color:#e8bd66;font:13px Arial,sans-serif;margin:0 0 12px}@media(max-width:800px){.rb-menu-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.rb-menu-grid{grid-template-columns:1fr}.rb-menu-page{padding:30px 14px}.rb-menu-photo{height:220px}}\n";

export default function Menu({ onAdd, addToCart, handleAddToCart }) {
  const [category, setCategory] = useState("All");
  const [search, setSearch] = useState("");
  const [localCartCount, setLocalCartCount] = useState(0);
  const cartHandler = onAdd || addToCart || handleAddToCart;
  const shown = useMemo(() => MENU_ITEMS.filter((item) =>
    (category === "All" || item.category === category) &&
    (item.name + " " + item.description + " " + item.category)
      .toLowerCase().includes(search.trim().toLowerCase())
  ), [category, search]);

  function addItem(item) {
    if (typeof cartHandler === "function") cartHandler(item);
    else {
      setLocalCartCount((count) => count + 1);
      // Local count only; pass your app's cart callback to integrate checkout.
    }
  }

  return (
    <main className="rb-menu-page">
      <style>{CSS}</style>
      <div className="rb-menu-wrap">
        <div className="rb-menu-heading">
          <span className="rb-menu-eyebrow">MADE WITH CARE</span>
          <h1>Our Menu</h1>
          <p>Made daily with fresh produce. Please ask about allergens.</p>
        </div>
        <input className="rb-menu-search" type="search" placeholder="Search dishes..."
          aria-label="Search dishes" value={search} onChange={(e) => setSearch(e.target.value)} />
        <div className="rb-menu-tabs" role="group" aria-label="Food categories">
          {CATEGORIES.map((name) => (
            <button type="button" key={name} className={category === name ? "active" : ""}
              aria-pressed={category === name} onClick={() => setCategory(name)}>{name}</button>
          ))}
        </div>
        {!cartHandler && localCartCount > 0 && <p className="rb-menu-cartnote">Items added: {localCartCount} (local preview)</p>}
        {shown.length === 0 ? <div className="rb-menu-empty">No dishes found. Try another search or category.</div> :
          <div className="rb-menu-grid">
            {shown.map((item) => (
              <article className="rb-menu-card" key={item.id}>
                <div className="rb-menu-photo">
                  <img src={item.image} alt={item.name} loading="lazy" />
                  {item.popular && <span className="rb-menu-popular">Popular</span>}
                </div>
                <div className="rb-menu-details">
                  <div className="rb-menu-title"><h3>{item.name}</h3><strong>Â£{item.price.toFixed(2)}</strong></div>
                  <p>{item.description}</p>
                  <button type="button" className="rb-menu-add" onClick={() => addItem(item)}>ï¼‹ Add to cart</button>
                </div>
              </article>
            ))}
          </div>}
      </div>
    </main>
  );
}
